import{_ as e,o as s,c as o,ag as i}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Política de Versionamento & Releases","description":"","frontmatter":{},"headers":[],"relativePath":"pt-br/21-politica-de-versionamento-e-releases.md","filePath":"pt-br/21-politica-de-versionamento-e-releases.md"}'),t={name:"pt-br/21-politica-de-versionamento-e-releases.md"};function n(l,a,r,d,p,c){return s(),o("div",null,[...a[0]||(a[0]=[i(`<h1 id="politica-de-versionamento-releases" tabindex="-1">Política de Versionamento &amp; Releases <a class="header-anchor" href="#politica-de-versionamento-releases" aria-label="Permalink to &quot;Política de Versionamento &amp; Releases&quot;">​</a></h1><blockquote><p><strong>Governança SemVer, Ciclo de Vida e Lançamentos no SoftForge</strong><br><em>Semantic Versioning 2.0.0 • Rolling Main • Monorepo Unificado • CHANGELOG Contínuo</em></p></blockquote><hr><h2 id="_1-visao-geral-e-filosofia" tabindex="-1">1. Visão Geral e Filosofia <a class="header-anchor" href="#_1-visao-geral-e-filosofia" aria-label="Permalink to &quot;1. Visão Geral e Filosofia&quot;">​</a></h2><p>O <strong>SoftForge</strong> foi concebido para ser utilizado tanto por desenvolvedores humanos quanto por <strong>Agentes Autônomos de IA</strong> que geram produtos de produção.</p><p>Para equilibrar inovação contínua e máxima previsibilidade operacional, adotamos o modelo <strong>SemVer Híbrido</strong>:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Main[&quot;Branch main&lt;br/&gt;(Rolling Release Contínuo)&quot;] --&gt;|Validação Verify| CI[&quot;Guardrails 100%&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CI --&gt;|release.py| Tag[&quot;Releases Formais&lt;br/&gt;(v1.0.0, v1.1.0, v2.0.0)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tag --&gt;|Sincroniza| Changelog[&quot;CHANGELOG.md&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tag --&gt;|Distribui| Downstream[&quot;Projetos &amp; Aplicações Derivadas&quot;]</span></span></code></pre></div><ol><li><strong>Branch <code>main</code> (Rolling Release Contínuo):</strong><br> O branch principal está sempre em estado deployável e pronto para uso imediato. Nenhum código quebra os guardrails de tipos, lint ou testes em <code>main</code>.</li><li><strong>Releases Formais SemVer (<code>vX.Y.Z</code>):</strong><br> Marcos oficiais congelados no tempo através de tags Git assinadas, acompanhados de notas detalhadas no <code>CHANGELOG.md</code> e releases no GitHub.</li><li><strong>Versão Única Global (Monorepo):</strong><br> A API (<code>apps/api</code>), o Frontend (<code>apps/web</code>), o catálogo de Temas (<code>themes/</code>), as Skills de IA e a documentação avançam sempre sob o mesmo número de versão.</li></ol><hr><h2 id="_2-estrutura-semver-2-0-0-major-minor-patch" tabindex="-1">2. Estrutura SemVer 2.0.0 (<code>MAJOR.MINOR.PATCH</code>) <a class="header-anchor" href="#_2-estrutura-semver-2-0-0-major-minor-patch" aria-label="Permalink to &quot;2. Estrutura SemVer 2.0.0 (\`MAJOR.MINOR.PATCH\`)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       v 1 . 2 . 4</span></span>
<span class="line"><span>         │   │   │</span></span>
<span class="line"><span>         │   │   └── PATCH: Correções de bugs, segurança e docs (sem alterar APIs)</span></span>
<span class="line"><span>         │   └────── MINOR: Novas fatias verticais, novos temas, rotas retrocompatíveis</span></span>
<span class="line"><span>         └────────── MAJOR: Quebras de contrato, remoção de rotas, migrações destrutivas</span></span></code></pre></div><h3 id="_1-major-vx-0-0" tabindex="-1">1. MAJOR (<code>vX.0.0</code>) <a class="header-anchor" href="#_1-major-vx-0-0" aria-label="Permalink to &quot;1. MAJOR (\`vX.0.0\`)&quot;">​</a></h3><ul><li><strong>Quando ocorre:</strong> Qualquer modificação que quebre compatibilidade com contratos anteriores.</li><li><strong>Exemplos no SoftForge:</strong><ul><li>Remoção ou alteração drástica de campos em schemas OpenAPI sem retrocompatibilidade.</li><li>Modificações destrutivas no banco de dados (exclusão ou renomeação de colunas/tabelas).</li><li>Alterações incompatíveis na especificação <code>softforge-theme.json</code> ou nos tokens CSS universais (<code>--sf-*</code>).</li></ul></li><li><strong>Política de Transição:</strong> As mudanças são lançadas diretamente no MAJOR, exigindo: <ol><li>Migração Alembic reversível.</li><li>Guia de migração passo a passo no <code>CHANGELOG.md</code>.</li></ol></li></ul><h3 id="_2-minor-v1-x-0" tabindex="-1">2. MINOR (<code>v1.X.0</code>) <a class="header-anchor" href="#_2-minor-v1-x-0" aria-label="Permalink to &quot;2. MINOR (\`v1.X.0\`)&quot;">​</a></h3><ul><li><strong>Quando ocorre:</strong> Novos recursos e fatias verticais adicionados de forma 100% retrocompatível.</li><li><strong>Exemplos no SoftForge:</strong><ul><li>Adição de uma nova fatia vertical em <code>apps/api/src/slices/</code> (ex: <code>crm</code>, <code>billing</code>, <code>storage</code>).</li><li>Novos endpoints HTTP ou novos campos opcionais em schemas existentes.</li><li>Migrações de banco aditivas (novas tabelas ou novas colunas com valores padrão).</li><li>Novos temas disponibilizados no catálogo <code>themes/</code>.</li><li>Novas skills ou regras no diretório <code>.agents/skills/</code>.</li></ul></li></ul><h3 id="_3-patch-v1-0-x" tabindex="-1">3. PATCH (<code>v1.0.X</code>) <a class="header-anchor" href="#_3-patch-v1-0-x" aria-label="Permalink to &quot;3. PATCH (\`v1.0.X\`)&quot;">​</a></h3><ul><li><strong>Quando ocorre:</strong> Correções de bugs, segurança, documentação ou melhorias internas de performance.</li><li><strong>Exemplos no SoftForge:</strong><ul><li>Correção de falha de validação ou cálculo em <code>service.py</code>.</li><li>Ajuste de responsividade ou visual em componentes do <code>apps/web</code>.</li><li>Atualização de dependências com vulnerabilidades (CVEs).</li><li>Correção de links e formatação em <code>docs/</code>.</li></ul></li></ul><hr><h2 id="_3-automacao-de-releases-com-release-py" tabindex="-1">3. Automação de Releases com <code>release.py</code> <a class="header-anchor" href="#_3-automacao-de-releases-com-release-py" aria-label="Permalink to &quot;3. Automação de Releases com \`release.py\`&quot;">​</a></h2><p>O SoftForge conta com um utilitário CLI exclusivo para orquestrar lançamentos com total garantia de integridade:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Executa a suíte de guardrails, atualiza arquivos e gera commit/tag Git:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/release.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Adiciona fatia de convites de equipe&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ou especifique uma versão explícita:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/release.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Lançamento oficial GA&quot;</span></span></code></pre></div><h3 id="o-que-o-release-py-executa-em-sequencia" tabindex="-1">O que o <code>release.py</code> executa em sequência: <a class="header-anchor" href="#o-que-o-release-py-executa-em-sequencia" aria-label="Permalink to &quot;O que o \`release.py\` executa em sequência:&quot;">​</a></h3><ol><li><strong>Validação de Guardrails:</strong> Executa <code>python tools/scripts/verify.py</code>. Se qualquer teste, contrato ou linter falhar, o processo é abortado imediatamente.</li><li><strong>Sincronização de Versões:</strong> Atualiza <code>apps/api/pyproject.toml</code>, <code>apps/web/package.json</code> e <code>docs/package.json</code>.</li><li><strong>Geração do Changelog:</strong> Analisa os commits Git recentes (Conventional Commits) e adiciona a nova seção no topo do <code>CHANGELOG.md</code>.</li><li><strong>Git Commit e Tag:</strong> Realiza o commit com mensagem <code>chore(release): release vX.Y.Z</code> e cria a tag anotada <code>vX.Y.Z</code>.</li></ol><hr><h2 id="_4-como-manter-seu-projeto-atualizado-com-o-softforge" tabindex="-1">4. Como Manter Seu Projeto Atualizado com o SoftForge <a class="header-anchor" href="#_4-como-manter-seu-projeto-atualizado-com-o-softforge" aria-label="Permalink to &quot;4. Como Manter Seu Projeto Atualizado com o SoftForge&quot;">​</a></h2><p>Para aplicações desenvolvidas com o SoftForge que desejam receber melhorias do framework upstream:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Adicionar o repositório oficial como upstream (caso tenha feito fork):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/omauriciofala/softforge.redepronta.com.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Buscar novas releases e tags:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Atualizar fatias ou o core para a última versão estável:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.1.0</span></span></code></pre></div><p>Se houver novas migrações de banco de dados, execute o validador:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/migrate.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/verify.py</span></span></code></pre></div>`,29)])])}const u=e(t,[["render",n]]);export{m as __pageData,u as default};
